CREATE TABLE change_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1), token TEXT NOT NULL CHECK(length(token)=32));
INSERT INTO change_state VALUES (1,lower(hex(randomblob(16))));
CREATE TRIGGER changed_profile_INSERT AFTER INSERT ON profile BEGIN UPDATE change_state SET token=lower(hex(randomblob(16))) WHERE singleton=1; END;
CREATE TRIGGER changed_profile_UPDATE AFTER UPDATE ON profile BEGIN UPDATE change_state SET token=lower(hex(randomblob(16))) WHERE singleton=1; END;
CREATE TRIGGER changed_profile_DELETE AFTER DELETE ON profile BEGIN UPDATE change_state SET token=lower(hex(randomblob(16))) WHERE singleton=1; END;
